import orders from './orders.json' with { type: 'json' };

const ALLOWED_KEYS = new Set(['order_id', 'include_history']);

const orderStatusInputSchema = {
  type: 'object',
  properties: {
    order_id: { type: 'string' },
    include_history: { type: 'boolean' }
  },
  required: ['order_id'],
  additionalProperties: false
};

function validateArgs(args) {
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object');
  }
  for (const key of Object.keys(args)) {
    if (!ALLOWED_KEYS.has(key)) {
      throw new Error(`Unknown field: ${key}`);
    }
  }
  if (!Object.prototype.hasOwnProperty.call(args, 'order_id')) {
    throw new Error('Missing required field: order_id');
  }
  if (typeof args.order_id !== 'string') {
    throw new Error('Invalid field: order_id must be a string');
  }
  if (Object.prototype.hasOwnProperty.call(args, 'include_history') &&
      typeof args.include_history !== 'boolean') {
    throw new Error('Invalid field: include_history must be a boolean');
  }
}

export async function listTools() {
  return [
    {
      name: 'order_status',
      description: 'Get the current status of an order, optionally with its chronological history.',
      inputSchema: orderStatusInputSchema
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'order_status') {
    throw new Error(`Unknown tool: ${name}`);
  }
  validateArgs(args);

  const { order_id, include_history = false } = args;
  const order = orders[order_id];
  if (!order) {
    throw new Error(`Order not found: ${order_id}`);
  }

  const text = include_history
    ? `Status: ${order.status}\nHistory: ${order.history.join(' -> ')}`
    : `Status: ${order.status}`;

  return {
    content: [{ type: 'text', text }]
  };
}

